import{_ as t,o,c as d,a3 as a}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"文件与存储","description":"","frontmatter":{},"headers":[],"relativePath":"backend/file.md","filePath":"backend/file.md","lastUpdated":1786258579000}'),c={name:"backend/file.md"};function r(s,e,i,n,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="文件与存储" tabindex="-1">文件与存储 <a class="header-anchor" href="#文件与存储" aria-label="Permalink to &quot;文件与存储&quot;">​</a></h1><p>文件能力分三块：<strong>文件库</strong>（元数据与多副本）、<strong>存储配置</strong>（后端在哪儿、怎么连）、<strong>导入导出中心</strong>（大批量数据的异步进出）。对应菜单目录 <code>/file</code> 与 <code>/setting</code> 下的存储配置页。</p><h2 id="数据模型-元数据与存储位置分离" tabindex="-1">数据模型：元数据与存储位置分离 <a class="header-anchor" href="#数据模型-元数据与存储位置分离" aria-label="Permalink to &quot;数据模型：元数据与存储位置分离&quot;">​</a></h2><p>这是理解整块能力的关键——<strong>一个文件（<code>SysFile</code>）可以有多个存储位置（<code>SysFileStorage</code>）</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SysFile（文件元数据，业务只认它）</span></span>\n<span class="line"><span>  ├─ SysFileStorage  ← 主副本（IsPrimary = true）：本地磁盘</span></span>\n<span class="line"><span>  └─ SysFileStorage  ← 备副本：对象存储 / CDN</span></span></code></pre></div><h3 id="sysfile-文件是什么" tabindex="-1"><code>SysFile</code>：文件是什么 <a class="header-anchor" href="#sysfile-文件是什么" aria-label="Permalink to &quot;`SysFile`：文件是什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>FileName</code> / <code>OriginalName</code> / <code>FileExtension</code></td><td>存储名 / 用户上传时的原名 / 扩展名</td></tr><tr><td><code>FileType</code> / <code>MimeType</code></td><td>分类与 MIME</td></tr><tr><td><code>FileSize</code></td><td>字节数（<strong>JSON 里是字符串</strong>，<code>long</code> 统一序列化为字符串）</td></tr><tr><td><code>FileHash</code> / <code>HashAlgorithm</code></td><td>内容哈希——<strong>秒传探测与去重的依据</strong></td></tr><tr><td><code>Width</code> / <code>Height</code> / <code>Duration</code></td><td>图片尺寸 / 媒体时长</td></tr><tr><td><code>ThumbnailFileId</code></td><td>缩略图指向另一条 <code>SysFile</code></td></tr><tr><td><code>UploadIp</code> / <code>UploadSource</code></td><td>上传来源审计</td></tr></tbody></table><h3 id="sysfilestorage-文件在哪儿" tabindex="-1"><code>SysFileStorage</code>：文件在哪儿 <a class="header-anchor" href="#sysfilestorage-文件在哪儿" aria-label="Permalink to &quot;`SysFileStorage`：文件在哪儿&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>FileId</code></td><td>归属文件</td></tr><tr><td><code>StorageType</code> / <code>StorageProvider</code> / <code>StorageConfigId</code></td><td>后端类型、提供方、用的哪份存储配置</td></tr><tr><td><code>BucketName</code> / <code>StorageRegion</code> / <code>StoragePath</code> / <code>FullPath</code></td><td>定位信息</td></tr><tr><td><code>InternalUrl</code> / <code>ExternalUrl</code> / <code>CdnUrl</code></td><td>内网 / 外网 / CDN 访问地址</td></tr><tr><td><code>IsPrimary</code></td><td><strong>主副本标识</strong>，读取默认走它</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么要拆两张表</p><p>迁移存储后端时（本地 → OSS）只需给同一个 <code>SysFile</code> 追加一条 <code>SysFileStorage</code> 并切换 <code>IsPrimary</code>，<strong>业务表里保存的 <code>FileId</code> 不用动</strong>。这也是下面「业务只存 fileId」这条约定成立的前提。</p></div><h2 id="存储配置-file-storage" tabindex="-1">存储配置（<code>/file/storage</code>） <a class="header-anchor" href="#存储配置-file-storage" aria-label="Permalink to &quot;存储配置（`/file/storage`）&quot;">​</a></h2><p><code>SysStorageConfig</code> 是<strong>落库的</strong>存储后端配置，可以按租户隔离、运行期切换：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>ConfigCode</code> / <code>ConfigName</code></td><td>配置编码与名称</td></tr><tr><td><code>StorageType</code></td><td><code>Local</code>(0) / <code>S3</code>(1) / <code>OSS</code>(2) / <code>COS</code>(3) / <code>MinIO</code>(4)</td></tr><tr><td><code>Endpoint</code> / <code>Region</code> / <code>BucketName</code></td><td>连接信息</td></tr><tr><td><code>AccessKeyId</code> / <code>SecretAccessKey</code></td><td>凭据（<strong>加密存储</strong>）</td></tr><tr><td><code>IsDefault</code></td><td>默认配置</td></tr><tr><td><code>IsEnabled</code> / <code>Sort</code> / <code>Remark</code></td><td>常规</td></tr></tbody></table><p>本地存储另有一份基础设施级配置在 <code>appsettings</code> 的 <code>XiHan:ObjectStorage:Local</code>（<code>RootPath</code> 默认 <code>wwwroot/uploads</code>、<code>UrlPrefix</code> 默认 <code>/uploads</code>）。</p><div class="warning custom-block"><p class="custom-block-title">本地存储的 URL 是根相对路径</p><p>本地存储返回 <code>/uploads/...</code> 这样的<strong>根相对路径</strong>，静态文件中间件挂在鉴权之前所以能匿名直链。</p><p>前后端<strong>同源</strong>时直接可用；<strong>线上不同源时必须拼上 <code>VITE_API_BASE_URL</code> 的 origin</strong>，否则浏览器会拿前端域名去请求而 404。仓库里的 <code>toAbsoluteFileUrl</code> / <code>useAvatarUrl</code> 已经处理，自己拼 URL 时别忘了。</p></div><h2 id="文件管理-file-library" tabindex="-1">文件管理（<code>/file/library</code>） <a class="header-anchor" href="#文件管理-file-library" aria-label="Permalink to &quot;文件管理（`/file/library`）&quot;">​</a></h2><p>上传、查看、下载、删除文件。几条约定：</p><div class="danger custom-block"><p class="custom-block-title">业务表存 fileId，不存 URL</p><p>把 URL 写进业务表会在两件事上出问题：换存储后端时全表 URL 失效；带签名的私有对象 URL 会过期。</p><p><strong>正确做法是业务表只存 <code>FileId</code></strong>，读取时由服务端解析出当前有效的访问地址。</p></div><ul><li><strong>秒传</strong>：上传前先按内容哈希探测，命中就直接复用已有 <code>SysFile</code>，不重复传输与落盘。注意探测未命中时响应的 <code>data</code> 字段会被 <code>WhenWritingNull</code> 整个省略——客户端要按 <code>isSuccess</code> 判定，不要判断 <code>data</code> 是否存在。</li><li><strong>上传走 <code>multipart/form-data</code></strong>：前端不要手工设 <code>Content-Type</code>，让浏览器自己带 boundary（<code>RequestClient</code> 检测到 <code>FormData</code> 会主动删掉该头）。</li><li><strong>缩略图是独立的 <code>SysFile</code></strong>，通过 <code>ThumbnailFileId</code> 关联，不是同一条记录的附属字段。</li></ul><h2 id="导出中心-file-export-center" tabindex="-1">导出中心（<code>/file/export-center</code>） <a class="header-anchor" href="#导出中心-file-export-center" aria-label="Permalink to &quot;导出中心（`/file/export-center`）&quot;">​</a></h2><p>大数据量导出不能占请求线程，走<strong>异步任务 + 队列消费</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>页面点「导出」</span></span>\n<span class="line"><span>   │ 提交 SysExportTask（Status=Pending，落查询快照与字段快照）</span></span>\n<span class="line"><span>   │ 事务提交后入 IRedisDelayQueue&lt;ExportTaskMessage&gt;</span></span>\n<span class="line"><span>   ▼</span></span>\n<span class="line"><span>ExportTaskHostedService 拉取 → 执行导出 → 写文件 → 回写 FileId/进度/终态</span></span>\n<span class="line"><span>   ▼</span></span>\n<span class="line"><span>页面轮询任务状态 → 完成后下载</span></span></code></pre></div><p><code>SysExportTask</code> 的关键字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>BusinessType</code></td><td>业务类型（如 <code>log.access</code>），决定用哪个导出 Provider</td></tr><tr><td><code>Scope</code></td><td>导出范围（当前搜索结果 / 全量等）</td></tr><tr><td><code>Format</code></td><td>导出格式（CSV 等）</td></tr><tr><td><code>Status</code> / <code>Progress</code> / <code>TotalCount</code> / <code>ProcessedCount</code></td><td>进度反馈</td></tr><tr><td><strong><code>QuerySnapshot</code></strong></td><td><strong>提交时的查询条件快照</strong></td></tr><tr><td><strong><code>FieldsSnapshot</code></strong></td><td><strong>提交时的字段与列设置快照</strong></td></tr><tr><td><code>FileId</code> / <code>FileName</code> / <code>FileSize</code></td><td>产物</td></tr><tr><td><code>ErrorMessage</code> / <code>StartedTime</code> / <code>FinishedTime</code></td><td>执行结果</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么要存两份快照</p><p>导出是异步的——用户提交后可能立刻改了搜索条件、调了列设置甚至关掉页面。存快照保证<strong>导出的内容与点击那一刻看到的一致</strong>，而不是与执行那一刻的界面状态一致。</p><p>这也意味着：修复导出内容的 bug 要看快照里存了什么，而不是看现在页面上是什么。</p></div><p>前端 Schema 页只要在 <code>PageSchema.resource.export</code> 里声明 <code>{ businessType, buildQuery }</code>，导出按钮就会走这条异步链路；未声明时退化为本地 CSV 导出。<strong>导出按钮的显隐由 <code>exportPermission</code> 精准门控</strong>，未声明该字段则该页不显示导出。</p><h3 id="崩溃恢复" tabindex="-1">崩溃恢复 <a class="header-anchor" href="#崩溃恢复" aria-label="Permalink to &quot;崩溃恢复&quot;">​</a></h3><p>后台服务启动时会复位崩溃残留的「执行中」任务并重投，否则一次异常重启会让一批任务永久卡在中间态。新增类似链路时别漏这一步，见 <a href="./caching#崩溃恢复">缓存与异步</a>。</p><h2 id="导入" tabindex="-1">导入 <a class="header-anchor" href="#导入" aria-label="Permalink to &quot;导入&quot;">​</a></h2><p><code>SysImportHistory</code> 记录导入批次。前端 Schema 页内置 <code>SchemaImportDialog</code>：下载模板 → 选文件 → CSV 解析 → <strong>预校验</strong> → 批量创建。</p><p>模板字段由页面的 <code>ListFieldSchema</code> 中 <code>importable</code> 为真的字段派生——和表格、导出共用同一份字段声明，不需要单独维护模板。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./../frontend/schema-page">Schema 驱动页面</a>：导入导出按钮怎么声明</li><li><a href="./caching">缓存与异步</a>：队列与后台消费机制</li><li><a href="./data-model#文件与任务">数据模型</a>：相关表结构</li><li><a href="./../configuration#xihan-objectstorage">配置参考</a>：本地存储路径与 URL 前缀</li></ul>',33)])])}const u=t(c,[["render",r]]);export{g as __pageData,u as default};
